// @generated by auto-design from design.config.ts. The auto-design motion profile (subtle).
// Use with Motion (import { motion } from "motion/react") or element.animate(). Durations are in seconds.

export const duration = { fast: 0.12, base: 0.18, slow: 0.26, reveal: 0.7 } as const;

export const ease = { out: [0.23, 1, 0.32, 1], inOut: [0.77, 0, 0.175, 1] } as const;

/** The same curves as CSS strings, for element.animate() and inline styles. */
export const css = {
  easeOut: "cubic-bezier(0.23, 1, 0.32, 1)",
  easeInOut: "cubic-bezier(0.77, 0, 0.175, 1)",
  spring: "cubic-bezier(0.23, 1, 0.32, 1)",
} as const;

/** For drag, layout changes and anything that follows the pointer. */
export const spring = { type: "spring", duration: 0.3, bounce: 0 } as const;

/** Entering elements: a fade from scale 0.97 with 4px of travel. Never from scale 0. */
export const enter = {
  initial: { opacity: 0, scale: 0.97, y: 4 },
  animate: { opacity: 1, scale: 1, y: 0 },
  transition: { duration: duration.base, ease: ease.out },
} as const;

export const exit = {
  opacity: 0, scale: 0.97,
  transition: { duration: duration.fast, ease: ease.inOut },
} as const;

/** Content arriving as it scrolls into view: data, sections, text. Never a response to a press. */
export const reveal = {
  initial: { opacity: 0, y: 8 },
  whileInView: { opacity: 1, y: 0 },
  viewport: { once: true, amount: 0.4 },
  transition: { duration: duration.reveal, ease: ease.out },
} as const;

/** Seconds between items in a staggered reveal. */
export const stagger = 0.04;

/** Brand animation timing (launch films, social posts): slower and larger than product UI. */
export const brand = { beat: 0.7, stagger: 0.12, hold: 1.3, travel: 2.2 } as const;

/** Whether loops (spinners aside) may move at all. */
export const ambient = true;
